export type EvidenceLevel='confirmed'|'probable'|'plausible'|'disputed'|'traditional'|'unsupported'|'disproven';
export type ContinuityDimension='function'|'type'|'population'|'name'|'breed';
export type TimelineEvent={id:string;era:number;position:number;evidence:EvidenceLevel;date:string;title:string;tag:string;summary:string;source:string;dimensions:ContinuityDimension[]};
export const eras=[{"id":1,"n":"I","title":"Deep prehistory","period":"before 3000 BCE","width":640},{"id":2,"n":"II","title":"Iron Age Europe","period":"1000–100 BCE","width":400},{"id":3,"n":"III","title":"Greece and Rome","period":"400 BCE – 400 CE","width":1080},{"id":4,"n":"IV","title":"Visigothic Hispania","period":"400–711","width":540},{"id":5,"n":"V","title":"Al-Andalus","period":"711–1492","width":720},{"id":6,"n":"VI","title":"Medieval Iberia","period":"1000–1500","width":1240},{"id":7,"n":"VII","title":"Early modern Iberia","period":"1450–1700","width":880},{"id":8,"n":"VIII","title":"Bourbon to Restoration","period":"1700–1900","width":840},{"id":9,"n":"IX","title":"The century of the track","period":"1900–2000","width":1280},{"id":10,"n":"X","title":"Law, genome, rescue","period":"2000–2026","width":960}] as const;
export const timelineEvents:TimelineEvent[]=[
{"id":"e001","era":1,"position":0.09,"evidence":"confirmed","date":"c. 17,000 BP","title":"Erralla","tag":"Erralla","summary":"A canid humerus from Erralla cave in Gipuzkoa, AMS-dated to 17,410–17,096 cal BP and genetically confirmed as Canis lupus familiaris, mtDNA haplogroup C — shared with other Magdalenian dogs. One of the oldest domestic dogs in Europe, and the deepest secure dog in Iberia. Its authors note this raises the possibility that wolf domestication in western Europe began earlier than had been proposed.","source":"Hervella et al., Journal of Archaeological Science: Reports 46:103706 (2022).","dimensions":[]},
{"id":"e002","era":1,"position":0.24,"evidence":"confirmed","date":"c. 15,800 BP","title":"The oldest genome-confirmed dog","tag":"Pınarbaşı","summary":"Nuclear and mitochondrial genomes from Pınarbaşı in Türkiye push the direct genetic record of dogs back roughly five thousand years. A genetically homogeneous dog population was already spread across Europe and Anatolia by 14,300 years ago. The authors are careful about what this does not settle: genetics cannot resolve where in the world, and how many times, dogs were domesticated.","source":"Marsh et al., Nature 651:995–1003 (2026); Bergström et al., Nature 651:986–994 (2026).","dimensions":[]},
{"id":"e003","era":1,"position":0.4,"evidence":"confirmed","date":"c. 7,900–7,570 cal BP","title":"Buried, not eaten","tag":"Muge & Sado","summary":"At the Muge shell-middens an almost complete dog was found without cut or burn marks — intentionally buried rather than consumed. A Sado valley burial at around 7,600 years is the oldest dog burial in southern Europe. Mesolithic Iberian dogs shared an aquatic diet with the humans they lived beside.","source":"Detry & Cardoso, JAS 37 (2010); Pires et al., JAS 105:116–129 (2019).","dimensions":[]},
{"id":"e004","era":1,"position":0.56,"evidence":"confirmed","date":"4200–3600 BCE","title":"Twenty-six dogs in the graves","tag":"Pit-grave dogs","summary":"Middle Neolithic necropolises around Barcelona held dogs deposited with the dead, aged from one month to six years, of homogeneous size, forty to fifty centimetres at the withers, eating a diet close to that of the humans. Ritual deposition of whole or partial dogs continues, in changing forms, into the Iron Age.","source":"Albizuri, Nadal, Martín, Gibaja et al., JAS: Reports 24:198–207 (2019).","dimensions":[]},
{"id":"e005","era":1,"position":0.74,"evidence":"confirmed","date":"c. 3500–3200 BCE","title":"Gracile hounds enter the picture","tag":"Hierakonpolis","summary":"The Painted Tomb at Hierakonpolis and Predynastic white cross-lined pottery show leggy, prick-eared hunting dogs held on leashes. The type is real and old. But Hendrickx also shows that wild fauna falls to about one per cent of Egyptian assemblages after 3800 BC: hunting imagery is elite and symbolic, not a census of working dogs.","source":"Hendrickx (2006, 2011); Case & Payne, JEA 48 (1962); Huyge, Archéo-Nil 24 (2014).","dimensions":[]},
{"id":"e006","era":1,"position":0.86,"evidence":"traditional","date":"c. 7000 BCE?","title":"Saharan rock art as proof","tag":"Tassili","summary":"The Tassili n’Ajjer and Acacus paintings are routinely cited as showing “graceful proto-sighthounds” nine thousand years ago. Dating Saharan rock art is notoriously insecure and the sighthound identification is interpretive. Suggestive of the antiquity of the type in the region; not evidence of any lineage.","source":"Discussed in the corpus against Hendrickx, Riemer, Förster & Darnell (2009).","dimensions":["type"]},
{"id":"e007","era":1,"position":0.95,"evidence":"unsupported","date":"The negative result","title":"A galgo-like sighthound in Iberian prehistory","tag":"Negative result","summary":"Across the whole Iberian archaeozoological literature, no study classifies any prehistoric Iberian dog as a sighthound. Sizes cluster at forty to fifty centimetres; Horard-Herbin and colleagues place Late Glacial dogs of northern and south-western Spain in the small class. Researchers document morphological diversity and deliberately avoid functional-type labels. This is reported as a negative finding, not as an absence of interest.","source":"Daza Perea (2017); Blázquez-Orta et al. (2022, 2024); Horard-Herbin, Tresset & Vigne (2014).","dimensions":["type","population"]},
{"id":"e008","era":2,"position":0.26,"evidence":"confirmed","date":"Iron Age","title":"Selection begins","tag":"Types appear","summary":"By the Celtic Iron Age, morphological selection is visible: shortened faces with the associated pathologies, and a widening range of withers heights. Ancient authors name some thirty “races” of dog by geographic origin and function — pet, hunting, war and guard — among them Gaulish hunting dogs including the vertragus and the Segusian hound.","source":"Horard-Herbin, Tresset & Vigne, Animal Frontiers 4(3):23–31 (2014).","dimensions":["type"]},
{"id":"e009","era":2,"position":0.66,"evidence":"traditional","date":"6th c. BCE","title":"“The Celts brought the galgo”","tag":"Celtic arrival","summary":"The standard opening line of the breed histories: Celtic migrations carry the sighthound into Iberia in the sixth century BC. It is repeated across breed clubs and pet sites and rests on no primary source. The Celtic association is genuine — but it is an association of the word and of a hunting practice, not a demonstrated movement of dogs.","source":"Breed literature; not established in the scholarly record.","dimensions":["population","name"]},
{"id":"e010","era":3,"position":0.04,"evidence":"confirmed","date":"c. 400 BCE","title":"Xenophon does not know coursing","tag":"Xenophon","summary":"The earliest surviving hunting treatise describes Laconian scent hounds driving hares into nets. Xenophon says the hare is caught “contrary to the nature of the animal, by accident” — a line Arrian would later seize on to prove that Xenophon had simply never seen a fast Celtic dog. Among his forty-seven recommended dog names is Hormé, Impulse.","source":"Xenophon, Cynegeticus III–VII (Perseus, Marchant Loeb).","dimensions":["function"]},
{"id":"e011","era":3,"position":0.19,"evidence":"confirmed","date":"Augustan","title":"The Vertraha, swifter than thought","tag":"Grattius","summary":"Grattius gives the first Latin catalogue of dogs by origin — “dogs belong to a thousand lands” — and for light hunting of hare recommends the Vertraha, coloured with yellow spots, swifter than thought or a winged bird, though less good at finding hidden game. The poem survives as 541 hexameters in a single manuscript of about 800 CE, mutilated at the end.","source":"Grattius, Cynegeticon 156, 202–208 (Duff & Duff, Minor Latin Poets, Loeb 1934).","dimensions":["function","type"]},
{"id":"e012","era":3,"position":0.3,"evidence":"confirmed","date":"c. 84–85 CE","title":"The vertragus gets its name","tag":"Martial","summary":"A two-line Saturnalia gift-tag gives the first explicit naming of the vertragus in Latin literature: the keen vertragus hunts not for himself but for his master, and will bring the hare to you unhurt. Martial was himself a Spaniard, from Bilbilis. The neighbouring epigrams are an Asturian horse and a Gaulish lapdog — a run of luxury imports.","source":"Martial, Epigrams XIV.200 (Apophoreta); Leary, Martial Book XIV (1996).","dimensions":["function","name"]},
{"id":"e013","era":3,"position":0.4,"evidence":"probable","date":"c. 123–126 CE","title":"Arrian, proconsul of Baetica","tag":"Arrian in Spain","summary":"A Greek verse inscription to Artemis found at Córdoba in 1968, dedicated by “Arrianus, proconsul,” offering the goddess verse better than gold or the spoils of the chase. Syme, Bosworth and Stadter all accept the identification with the author of the Cynegeticus. The caveat: formal analysis of the marble suggests it may be an early third-century copy — or a different Arrianus.","source":"Tovar (1971, 1975); Bosworth, GRBS 17 (1976); Syme, HSCP 86 (1982); Stadter (1980).","dimensions":[]},
{"id":"e014","era":3,"position":0.44,"evidence":"unsupported","date":"The embellishment","title":"“Arrian first saw the vertragus in Spain”","tag":"","summary":"Nothing in the Cynegeticus places the vertragus or coursing in Hispania; both are Celtic and Gaulish throughout. The Córdoba stone says nothing about hunting hares. The story traces to a 2011 legal-history blog reporting a breed writer’s suggestion, and has been repeated ever since as though it were in the text.","source":"Absent from Arrian; traced in the corpus to secondary web sources.","dimensions":[]},
{"id":"e015","era":3,"position":0.53,"evidence":"confirmed","date":"c. 136–146 CE","title":"Arrian writes the book on coursing","tag":"Cynegeticus","summary":"The richest ancient source. The swift Celtic dogs are called ouertragoi not after any country but after their speed. Arrian describes their eyes, their coats, the four Celtic ways of coursing on horseback, and insists that the point is the race and not the kill — he dismounts to save hares and strikes dogs that kill a good one. His own grey-eyed bitch was called Hormé, and he calls her most swift, most wise, most divine.","source":"Arrian, Cynegeticus 3.6, 4–6 (Roos, Teubner; Phillips & Willcock 1999; Dansey 1831).","dimensions":["function","type"]},
{"id":"e016","era":3,"position":0.65,"evidence":"confirmed","date":"after 212 CE","title":"An Iberian dam","tag":"Oppian","summary":"In a long breeding scheme, Pseudo-Oppian pairs the breeds: Arcadian with Elean, Cretan with Paeonian, and a Sarmatian sire with an Iberian dam — “so shall you mix the breeds aright; but far best of all it is that the breeds should remain pure.” A direct classical mention of an Iberian hunting bitch.","source":"Pseudo-Oppian, Cynegetica I.393–400 (Mair, Loeb 1928).","dimensions":[]},
{"id":"e017","era":3,"position":0.74,"evidence":"confirmed","date":"283/284 CE","title":"Hounds of Spanish blood","tag":"Nemesianus","summary":"Nemesianus tells the hunter not to rear only Spartan or Molossian whelps: Britain sends a swift sort, and one should not disdain the Pannonian pedigree, “nor those whose progeny springs from Spanish blood.” The most explicit classical notice of Spanish hunting stock — though listed evenly beside Britain, Pannonia, Libya and Tuscany, not singled out.","source":"Nemesianus, Cynegetica 224ff (Duff & Duff, Loeb 1934).","dimensions":["population"]},
{"id":"e018","era":3,"position":0.82,"evidence":"unsupported","date":"4th c.","title":"The leaping galgo at La Olmeda","tag":"","summary":"Breed literature repeatedly describes a galgo pursuing a hare on the great hunting mosaic at La Olmeda. The scholarly descriptions of that oecus pavement record a big-game venatio — lions, leopards, bear, tigress, and a wild boar cornered by a generic pack. The coursing galgo is not in them.","source":"Palol (1982); Abásolo & Martínez (2012); Abásolo, Los mosaicos de La Olmeda (2013).","dimensions":[]},
{"id":"e019","era":3,"position":0.88,"evidence":"confirmed","date":"3rd–4th c. CE","title":"Named hounds, named hares","tag":"Mérida & Córdoba","summary":"Roman-Iberian object records now resolve this evidence directly. At Mérida, the AVRA mosaic shows a dog hunting a hare; excavator Félix Palma García calls it ‘más bien un galgo’ and treats AVRA as perhaps the dog's name. At Corduba, the Thalassius mosaic names Nimbus and Lateras while the excavation report describes them pursuing a hare. The official MNAR record for Suárez Somonte independently confirms a late-Roman hare-hunt mural panel. These objects establish hunting function and animal naming culture, not a documented population bridge to the modern breed.","source":"Object_Record_Merida_AVRA_Hare_Mosaic.md; Object_Record_Thalassius_Nimbus_Lateras_Mosaic.md; Object_Record_Suarez_Somonte_Hare_Hunt.md.","dimensions":["function","type","name"]},
{"id":"e020","era":3,"position":0.94,"evidence":"traditional","date":"The identification","title":"“The mosaic dogs are Galgos Españoles”","tag":"","summary":"Spanish and Portuguese scholars use galgo and lebrel descriptively, for the gracile coursing dogs that really are there. No peer-reviewed archaeologist identifies any depicted dog with the modern breed. That link appears only in kennel-club and popular literature, and rests on textual argument and etymology rather than on art-historical breed identification.","source":"Assessment of the mosaic scholarship in the corpus.","dimensions":["type","breed"]},
{"id":"e021","era":3,"position":0.99,"evidence":"disproven","date":"Non-existent","title":"The “Codex Romanicus”","tag":"","summary":"Cited in popular accounts as a Roman authority on hunting dogs and territorial administration. No such text exists. The label appears to conflate the real Cynegetica tradition, or Pliny’s encyclopedia, with the names of the late Roman legal codices — Gregorianus, Theodosianus, Justinianus. “Codex Romanus” is a real term, but it denotes a Catullus manuscript and an illustrated Virgil.","source":"Verdict recorded in the corpus, Batch 03.","dimensions":[]},
{"id":"e022","era":4,"position":0.13,"evidence":"confirmed","date":"506","title":"Canon 55 of the Council of Agde","tag":"Agde","summary":"Bishops, priests and deacons are forbidden to keep canes ad venandum or hawks, with graduated suspensions — three months for a bishop, two for a priest, one for a deacon. The single explicit hunting-dog reference of the whole Visigothic realm. It proves that elite hunting with dogs mattered enough to legislate against, and it names no breed at all.","source":"Munier (ed.), Concilia Galliae, CCSL 148 (1963); numbered 52 in the MGH Hispana rubric-list.","dimensions":["function"]},
{"id":"e023","era":4,"position":0.4,"evidence":"confirmed","date":"c. 615–630s","title":"Isidore: boldness, or speed","tag":"Isidore","summary":"“In dogs there are two qualities: either fortitudo or velocitas.” It is the closest Isidore comes to a functional taxonomy, and velocitas is exactly what a coursing hound is bred for. But he names no breed, no vertragus, no sighthound, and gives no Iberian detail. He is a compiler working from Pliny and Solinus, not an observer of Spanish hunting.","source":"Isidore, Etymologiae XII.2.25–28 (Lindsay 1911; Barney et al. 2006).","dimensions":[]},
{"id":"e024","era":4,"position":0.36,"evidence":"disproven","date":"The misattribution","title":"“Isidore gives the etymology of galgo”","tag":"","summary":"He does not. The word does not appear in his dog chapter. The canis gallicus derivation comes from later lexicography, not from the Etymologiae. The long passage often quoted from him — “numerous breeds of dogs… some track, others guard” — is a twelfth-century bestiary expansion, not Isidore’s text.","source":"Text check against Lindsay/LacusCurtius; RAE derivation via canis gallicus.","dimensions":["name"]},
{"id":"e025","era":4,"position":0.64,"evidence":"confirmed","date":"654","title":"A law code with no hunting dog","tag":"Liber Iudiciorum","summary":"The Visigothic Code treats dogs only in Book VIII, Title IV — as vicious animals creating liability, and implicitly as property. Its only hunting provisions concern traps and snares for wild beasts, and mention no dogs at all. A code that legislates in detail on bees, pigs, straying cattle and stolen cattle-bells has no legal category of hunting dog.","source":"Zeumer, MGH Leges I (1902); Scott, The Visigothic Code (1910), VIII.IV.XIX–XX, XXII–XXIII.","dimensions":[]},
{"id":"e026","era":4,"position":0.87,"evidence":"unsupported","date":"400–711","title":"A bridge of silence","tag":"The gap","summary":"Coursing is documented in Roman Hispania and again from the eleventh century. For the two Visigothic centuries between, nothing confirms or denies that the practice survived. Latin remained the written language and Roman estate structures persisted, which favours general continuity; no Visigothic hunting treatise exists, and no securely dated corpus of Visigothic hunting-dog remains has been published. Unsupported here means the archive is silent, not that the dogs stopped running.","source":"Collins, Visigothic Spain 409–711 (2004); Thompson, The Goths in Spain (1969).","dimensions":["function","population"]},
{"id":"e027","era":5,"position":0.12,"evidence":"confirmed","date":"mid-9th c.","title":"The Falcon and Dog Book","tag":"al-Mutawakkili","summary":"Compiled by al-Bazyar for the caliph al-Mutawakkil, covering what was known about falcons and dogs — above all their treatment in illness, since the chase was virtually a court ritual. Veterinary care of hunting dogs is present in the text. It survives through a thirteenth-century Tunisian compilation.","source":"Akasoy & Georges (eds.), Das Falken- und Hundebuch des Kalifen al-Mutawakkil (De Gruyter, 2005).","dimensions":[]},
{"id":"e028","era":5,"position":0.45,"evidence":"confirmed","date":"late 12th c.","title":"The chapter that is missing","tag":"Ibn al-ʿAwwām","summary":"The greatest agricultural treatise in medieval Arabic, written in Almohad Seville, survives more or less complete in thirty-four chapters — 585 plants, more than fifty fruit trees. A thirty-fifth chapter, on dogs, was planned, and no trace of it survives. It is the emblem of this period: the record is not hostile to dogs, it simply does not preserve them.","source":"Filāḥa Texts Project (filaha.org); Sarton, Introduction to the History of Science II, 424–25.","dimensions":[]},
{"id":"e029","era":5,"position":0.58,"evidence":"confirmed","date":"c. 1250","title":"Knowledge crosses the Strait","tag":"Libro de los animales","summary":"Al-Bazyar’s book is translated into Castilian — the first Castilian hunting treatise — and into Latin for Frederick II. It feeds directly into Alfonso XI’s Libro de la montería and shapes the Castilian manual tradition through the seventeenth century. This is the best-documented Islamic-to-Christian transmission in the whole story. It is a transfer of knowledge, not of dogs.","source":"Fradejas Rueda, editions of the Libro de los animales que cazan; De Gruyter transmission note.","dimensions":[]},
{"id":"e030","era":5,"position":0.73,"evidence":"traditional","date":"The origin story","title":"“The Moors brought the Sloughi”","tag":"Moorish origin","summary":"That the galgo descends from, or was crossed with, Sloughis brought across the Strait. Trade and political integration under the Almoravids and Almohads make canine movement plausible in principle — but no primary record of dogs, as opposed to cloth, copper, skins and hunting cats, has been found crossing. And where the galgo has actually been genotyped it clusters with European sighthounds, while the Sloughi was excluded from that study as an admixed outlier.","source":"Li/Zhang et al., MBE 40(8):msad158 (2023); Parker et al. (2017); Plassais et al. (2019).","dimensions":["population"]},
{"id":"e031","era":5,"position":0.81,"evidence":"unsupported","date":"Still untested","title":"A Galgo–Sloughi genetic comparison","tag":"","summary":"No peer-reviewed study has ever compared Galgo and Sloughi DNA head to head. The Dog10K project has sampled both, but no published analysis places one relative to the other. The only claim of such a comparison comes from a breed-club microsatellite dataset, which concluded that Sloughi, Saluki, Azawakh and Galgo are genetically distinct — and admitted it had essentially no genuine North African Sloughi samples.","source":"Dog10K consortium, Genome Biology 24:187 (2023); Sloughi Club UK dataset.","dimensions":["population"]},
{"id":"e032","era":5,"position":0.91,"evidence":"confirmed","date":"The lexical test","title":"What the vocabulary shows","tag":"Vocabulary","summary":"Arabic gave Spanish roughly four thousand words — about eight per cent of the dictionary — concentrated in agriculture, architecture, administration and science. In the hunting field the borrowings are falconry terms. Galgo is Latin, from canis gallicus; podenco is not Arabic. The linguistic evidence argues against a strong Arabic imprint on the Spanish sighthound tradition.","source":"Dworkin, on Arabic influence in Spanish; DCECH.","dimensions":["name"]},
{"id":"e033","era":6,"position":0.03,"evidence":"probable","date":"1073","title":"The word arrives","tag":"galgo leporario","summary":"Galgo leporario — the Gaulish dog that chases hares — is attested in texts of 1073. The noun is from Vulgar Latin canis gallicus by ellipsis. Continuity of name from here is genuinely strong. What a name cannot do on its own is carry a population.","source":"Corominas, DCECH; RAE.","dimensions":["name"]},
{"id":"e034","era":6,"position":0.08,"evidence":"probable","date":"3 Nov 1081","title":"Urso, a black galgo","tag":"Eslonza deed","summary":"A deed in the cartulary of Eslonza, León, donating an estate at Villacantol, includes “Urso galgo colore nigro” — a black galgo valued at one hundred silver solidi. The earliest named individual galgo in the record. The wording is repeated verbatim across the secondary literature, which is itself a warning sign; the archival transcription still wants primary verification. Note the common mislabelling of the cartulary as “Silos.”","source":"Cartulario de Eslonza; cited widely, primary check outstanding.","dimensions":["name"]},
{"id":"e035","era":6,"position":0.13,"evidence":"confirmed","date":"c. 1200","title":"El Cid does not hunt","tag":"Mio Cid","summary":"A concordance check of the Cantar de Mio Cid finds no galgo, lebrel, sabueso, alano, liebre, montería, caza or cazador anywhere in the poem. The only dog-word is canes, thrown as an insult at the Infantes de Carrión. The only hunting image is the empty falcon perches at verses 4–5 — a picture of loss, not of the chase.","source":"Menéndez Pidal; Montaner (2007); Fuentes, Olivar 8:10 (2007); RAE Diccionario histórico.","dimensions":[]},
{"id":"e036","era":6,"position":0.17,"evidence":"disproven","date":"The claim","title":"“El Cid favoured the galgo”","tag":"","summary":"A staple of breed marketing, with no textual support of any kind. The concordance is decisive: the poem that supposedly documents his taste for sighthounds contains no hunting-hound vocabulary at all.","source":"Absence in the Cantar; documented in the corpus, Batch 07.","dimensions":[]},
{"id":"e037","era":6,"position":0.21,"evidence":"confirmed","date":"mid-12th c.","title":"Fuero de Coria","tag":"Coria","summary":"“Whoever kills a galgo, or a caravo, or a tracking dog — for the galgo, two maravedís to its owner.” The frontier charters begin pricing the coursing hound, and they do it for townsmen, not only for lords.","source":"Fuero de Coria (Alfonso VII); Biblioteca Virtual Miguel de Cervantes.","dimensions":["function"]},
{"id":"e038","era":6,"position":0.26,"evidence":"disproven","date":"The date","title":"“The Fuero de Salamanca, 9th century”","tag":"","summary":"The charter is a composite fuero extenso in Leonese romance whose materials accrete from the early twelfth century and take definitive form in the second half of the thirteenth. The “ninth century” label conflates the charter with the repopulation of the Duero valley described as background in an 1870 preliminary discourse.","source":"Martín Martín & Coca, Fuero de Salamanca (1987), 15–18; CORDE dates the reference text to c. 1300.","dimensions":[]},
{"id":"e039","era":6,"position":0.3,"evidence":"probable","date":"12th–13th c.","title":"What Salamanca actually says","tag":"Salamanca","summary":"“Any man who kills a herding dog, or a podenco, or a galgo, shall pay two maravedís, and for a caravo, five sueldos.” The provision is real and the wording reliable. The article number is the one remaining citation-grade gap: it has not yet been pinned against a scholarly concordance.","source":"Castro & Onís, Fueros leoneses (1916); Alvar, El fuero de Salamanca (1968).","dimensions":[]},
{"id":"e040","era":6,"position":0.34,"evidence":"disproven","date":"The figure","title":"“Three hundred sueldos for killing a galgo”","tag":"","summary":"The most-repeated single fact about the medieval galgo, and it matches no primary edition. The comparable charters give two maravedís at Coria, Cáceres and Usagre, twenty sueldos at Teruel, five aureos at Cuenca, five maravedís at Zorita. None approaches three hundred.","source":"Surveyed against the Ureña, Gorosch and Ilarregui editions.","dimensions":[]},
{"id":"e041","era":6,"position":0.39,"evidence":"confirmed","date":"c. 1189","title":"De canibus","tag":"Fuero de Cuenca","summary":"Under its own rubric “On dogs,” the most elaborate of the Castilian charters prices the hunting dogs: alanum, vel sabusum, vel galgum — five aureos. A stolen podenco costs ten mencales. The galgo sits in a graded market of working animals with the tracker and the catch-dog.","source":"Ureña ed. (1935), 712–715.","dimensions":["function"]},
{"id":"e042","era":6,"position":0.44,"evidence":"confirmed","date":"13th c.","title":"Break its leg, pay as if you killed it","tag":"Usagre","summary":"“Qui matare galgo… pectet II morauetis domino suo… Et si al galgo quebrantare pierna al tanto, pectet como si lo matasse.” Laming a coursing hound and killing it are the same offence, because a lamed galgo is no longer a galgo. The law understands exactly what the dog is for.","source":"Fuero de Usagre §§104–105, Ureña & Bonilla ed. (1907).","dimensions":["function"]},
{"id":"e043","era":6,"position":0.49,"evidence":"confirmed","date":"13th c.","title":"The collar is in the statute","tag":"Navarra","summary":"The Fuero General de Navarra penalises the theft of “galgo que caza, que traye correya al pescueza, con sortiella” — a galgo that hunts, wearing a strap at its neck, with a ring — at sixty sueldos. The working collar, familiar from the heraldic lebrel, is written into the definition of the protected animal.","source":"Fuero General de Navarra, lib. V tít. VII cap. XVIII, Ilarregui ed.","dimensions":["function","type"]},
{"id":"e044","era":6,"position":0.26,"evidence":"plausible","date":"12th c.","title":"San Baudelio de Berlanga","tag":"San Baudelio","summary":"The hunting murals of the Soria hermitage show sighthounds; breed literature describes “three galgos apparently identical to the ones we see today.” The dogs are certainly there. The breed identification is an art-historical inference, made by enthusiasts rather than by art historians, and belongs at the level of type rather than lineage.","source":"Breed literature; scholarly breed attribution not established.","dimensions":["type"]},
{"id":"e045","era":6,"position":0.57,"evidence":"confirmed","date":"c. 1256–65","title":"Hunting as a virtue of kingship","tag":"Siete Partidas","summary":"“The king should be skilled and knowing in things that turn to pleasure” — and among them the ancients found none more useful than the hunt, good for health, for relieving cares and anger, and as training analogous to war. A companion law bars clerics from keeping hawks or hunting dogs. The Partidas’ own dating is contested, which any citation of them should carry.","source":"Partidas II.V.XX and I (RAH ed., 1807); García-Gallo dating debate.","dimensions":["function"]},
{"id":"e046","era":6,"position":0.62,"evidence":"unsupported","date":"Negative result","title":"The word “galgo” in the Partidas","tag":"","summary":"Searches did not locate an explicit occurrence of galgo or galga in the Partidas’ hunting and coursing laws themselves. Recorded here as a negative result rather than passed over, because the corpus treats a failed search as data.","source":"Negative result, Batch 06.","dimensions":["name"]},
{"id":"e047","era":6,"position":0.7,"evidence":"confirmed","date":"c. 1325–26","title":"Juan Manuel writes about falcons","tag":"Libro de la caza","summary":"The earliest original Castilian book on hunting with birds, and it deals only with the high-flying falcons, setting aside goshawks. It survives incomplete, in a single manuscript. Juan Manuel promised further sections that would have united falconry and hound-hunting; they were never written or never survived. On galgos it says essentially nothing.","source":"BNE MS 6376; Fradejas Rueda, Don Juan Manuel y el Libro de la caza (2001).","dimensions":[]},
{"id":"e048","era":6,"position":0.79,"evidence":"confirmed","date":"c. 1350","title":"A veterinary treatise for the wrong dogs","tag":"Libro de la montería","summary":"Alfonso XI’s manual runs to three books: the organisation of the hunt, then a genuine early treatise of canine medicine and breeding, then a gazetteer of the best hunting country in Castile, León and Granada. Its dogs are the sabueso and the alano, because its quarry is boar and bear. The galgo, a hare-courser, falls outside a big-game manual — which is why kings commissioned montería and falconry treatises and never a coursing one.","source":"Escorial MS Y.II.19; Seniff ed. (1983); Fradejas Rueda (1992); twelve surviving manuscripts.","dimensions":[]},
{"id":"e049","era":6,"position":0.88,"evidence":"confirmed","date":"1391","title":"The Order of the White Sighthound","tag":"Lebrel Blanco","summary":"Carlos III of Navarre founds a chivalric order under the sign of the lebrel blanco. Sighthounds lie at the feet of Queen Leonor of Navarre on her tomb of 1419, and the collared lebrel becomes the emblematic Iberian heraldic dog — the greyhound outline chosen precisely so the animal could not be mistaken for a wolf.","source":"Morales Muñiz (2022); Cummins, The Art of Medieval Hunting (2003).","dimensions":["type"]},
{"id":"e050","era":6,"position":0.93,"evidence":"plausible","date":"Across the charters","title":"Coursing without rank","tag":"Cross-class","summary":"Unlike England and France, where sighthound coursing was reserved to the nobility, the fueros protect galgos across frontier concejo society — caballeros villanos and commoners alike. Andalusian ethnography later describes the galgo as both the necessary ally of landless day-labourers and an object of value among the aristocracy. Coursing needs only dogs and open ground.","source":"Fuero evidence plus ethnographic literature; corroborated later by the Don Quixote image.","dimensions":["function"]},
{"id":"e051","era":6,"position":0.985,"evidence":"unsupported","date":"The inversion","title":"“Arrian said coursing knew no class”","tag":"","summary":"A breed-literature paraphrase that reverses its source. Arrian describes exactly three classes of Celtic courser: wealthy men who send others out to find hares, a less opulent second sort who beat the ground themselves on horseback, and a third who go on foot — “really workmen at the sport.” The cross-class character of Iberian coursing is well evidenced. It is just not evidenced by this.","source":"Arrian, Cynegeticus (Dansey trans.); paraphrase traced in the corpus.","dimensions":[]},
{"id":"e052","era":7,"position":0.05,"evidence":"probable","date":"1493","title":"The first European dogs in the Americas","tag":"Columbus","summary":"Greyhounds — lebreles — were the first European dogs carried across, on Columbus’s second voyage. The primary expectation was that they would hunt, feeding the colony until European livestock became self-sustaining. Alanos and mastiffs were provisioned separately, in Fonseca’s order, to guard herds and people.","source":"Ensminger, Colonial Latin American Review 31(3):354–380 (2022).","dimensions":["function"]},
{"id":"e053","era":7,"position":0.11,"evidence":"probable","date":"March 1495","title":"Vega Real","tag":"Vega Real","summary":"Twenty dogs are turned on the forces of the caciques opposing Columbus. From here the use of the dogs begins to shift from hunting towards war and repression. The chronicle numbers — hundreds of Spaniards against tens of thousands — are propaganda and should be read as such; the change in function is the fact.","source":"Ensminger (2022), against Varner & Varner, Dogs of the Conquest (1983).","dimensions":[]},
{"id":"e054","era":7,"position":0.18,"evidence":"disputed","date":"The argument","title":"What were the conquest dogs?","tag":"Mastiff or lebrel?","summary":"Varner and Varner called them mastiffs, and that reading is still the one repeated everywhere. Ensminger argues from the chronicle vocabulary that the dogs at Vega Real were lebreles — sighthounds, repurposed hunters — and notes that Spanish writers themselves distinguished the types. Las Casas’s own word, in 1552, is lebreles. Credible readings differ; the corpus records the disagreement rather than resolving it.","source":"Varner & Varner (1983); Ensminger (2022); Piqueras, Universitat de Barcelona.","dimensions":["type"]},
{"id":"e055","era":7,"position":0.25,"evidence":"confirmed","date":"1552","title":"Aperreamiento","tag":"Las Casas","summary":"Las Casas records dogs deliberately trained so that on seeing an Indian they tore him to pieces, and a public butchery of human flesh kept at Popayán to feed them. His Brevísima relación is a polemic and its quantities are unreliable; its testimony on method is not in doubt. The galgo’s history includes this.","source":"Las Casas, Brevísima relación de la destrucción de las Indias (1552).","dimensions":[]},
{"id":"e056","era":7,"position":0.45,"evidence":"confirmed","date":"1 Aug 1556","title":"A whole book about dogs","tag":"Juan Vallés","summary":"The treasurer-general of Navarre finishes a six-book hunting treatise whose sixth book is entirely on dogs. He names his three sources — Alfonso XI, the Portuguese Livro da montaria, and a French book, Fébus — and says he declined to follow Alfonso on dogs because he had already written copiously on them himself. It was never printed in his lifetime and survives in eleven manuscript copies.","source":"Fradejas Rueda ed., Universidad de Valladolid; BNE 3127, 3335, 3379, 3382; RAE 8; Colombina 82-6-12.","dimensions":[]},
{"id":"e057","era":7,"position":0.58,"evidence":"confirmed","date":"1582","title":"Argote de Molina puts it in print","tag":"Argote 1582","summary":"Alfonso XI’s montería is printed at Seville by Andrea Pescioni with Argote’s own Discurso — the first Spanish hunting book to describe hunting in the Americas. The Discurso preserves an Andalusian scene: in the Duque de Arcos’s wood at Benamahoma the monteros loose two or three lebreles o alanos de traylla, which go off at full fury and are found fastened on the boar’s ears.","source":"Argote de Molina, Discurso (Seville, 1582).","dimensions":[]},
{"id":"e058","era":7,"position":0.73,"evidence":"confirmed","date":"1605","title":"“…y galgo corredor”","tag":"Don Quixote","summary":"A lance in the rack, an ancient shield, a lean hack — and a running galgo. Cervantes uses the dog in the novel’s first sentence as the cheapest possible marker of hidalgo status: the one luxury a ruined gentleman still keeps. No document of the period says more about what the galgo meant socially.","source":"Cervantes, Don Quixote I.1 (1605).","dimensions":["function"]},
{"id":"e059","era":7,"position":0.87,"evidence":"confirmed","date":"17th c.","title":"The nouns come loose","tag":"Terminology","summary":"Stevens’s dictionary makes the lebrel an Irish greyhound while noting some use it for a common greyhound, “which is not proper, those being called gálgos” — then elsewhere calls the galgo a large greyhound, and renders lebreles de presa as “Wolf Dogs.” Florio and Torriano translate both alano and levriero as greyhound. The function was stable across three centuries; the vocabulary was not.","source":"Salas (1950); Oviedo (1548); Stevens; Florio (1611); Torriano (1659).","dimensions":["name"]},
{"id":"e060","era":8,"position":0.07,"evidence":"confirmed","date":"1755","title":"Buffon’s table of dogs","tag":"Buffon","summary":"Thirty-odd races descending from a single ancestral stock, varying by climate, food and domestication — the dog is bare in the hottest countries and “dressed in a fine silky coat in Spain.” These are varieties, not breeds. The modern idea of a breed with a written standard and a closed studbook is a late-nineteenth-century invention, which Spain adopts around 1911.","source":"Buffon, Histoire naturelle, dog volume (1755).","dimensions":["breed"]},
{"id":"e061","era":8,"position":0.13,"evidence":"unsupported","date":"The attribution","title":"“Buffon named a lévrier d’Espagne”","tag":"","summary":"Not confirmable in the primary text. The greyhound-type entries reliably associated with his scheme are the lévrier and the Italian, Irish, Neapolitan and Turkish greyhounds. The line usually quoted about small greyhounds coming from England, Spain and Portugal descends from an older French dictionary tradition, not from Buffon.","source":"Primary-text check outstanding; line traced to the Furetière lineage.","dimensions":[]},
{"id":"e062","era":8,"position":0.29,"evidence":"confirmed","date":"18 Oct 1793","title":"Madrid’s veterinary school opens","tag":"Veterinaria","summary":"Fourteen students, two Alfort-trained directors, and a curriculum overwhelmingly about horses — the word veterinaria itself descends from albéitar, the horse-healer. There is no evidence the early school produced any scientific description of the galgo. Its surviving teaching collection runs more to a five-legged dog skeleton than to breed anatomy.","source":"Real Escuela de Veterinaria de Madrid, opened by Real Orden of 9 Sept 1788.","dimensions":[]},
{"id":"e063","era":8,"position":0.45,"evidence":"confirmed","date":"Early 19th c.","title":"“A los galgos del Rey…”","tag":"The proverb","summary":"“The King’s galgos don’t var the hare get away” — a proverb turned against the government of Fernando VII. For most of this period the galgo appears in the record less as a subject of technical description than as a figure: of rural Castile, of the impoverished hidalgo, and here of a state that catches whatever it goes after.","source":"Nineteenth-century Spanish proverb literature.","dimensions":[]},
{"id":"e064","era":8,"position":0.62,"evidence":"unsupported","date":"The export story","title":"“The galgo fathered the English Greyhound”","tag":"Greyhound origin","summary":"Repeated by the Spanish kennel club and by breed sites everywhere: galgos exported to England and Ireland in the sixteenth to eighteenth centuries, becoming a parent of the modern Greyhound. A targeted review of the authoritative Victorian writers found the opposite emphasis. Youatt (1845) names no Spanish greyhound and assigns the dogs of speed to the Celtic nations; Walsh (1853) argues for a Celtic origin; nothing was verified in Jesse (1866). No named breeder, kennel or date has been found for any such importation. The well-documented gene flow runs the other way, and later.","source":"Youatt, The Dog (1845); Walsh, The Greyhound (1853); Jesse, Researches (1866). Negative result — not proven absent.","dimensions":["population"]},
{"id":"e065","era":8,"position":0.79,"evidence":"confirmed","date":"10 Jan 1879","title":"The Hunting Law","tag":"1879 Hunting Law","summary":"The first modern Spanish hunting statute regulates coursing with galgos directly. Article 34 bars it on cultivated land from 1 March to 15 October — sowing to harvest, and in vineyards from bud to vintage. Article 35 requires a special governor’s licence at twenty-five pesetas, valid one year for six persons and ten dogs. The law is proof that coursing was widespread enough to threaten crops nationwide, and organised enough to be counted in cuadrillas.","source":"Ley de Caza, 10 January 1879, arts. 34–35; Gaceta de Madrid.","dimensions":["function"]},
{"id":"e066","era":8,"position":0.9,"evidence":"confirmed","date":"1888","title":"Four pairs of hares","tag":"Argentina 1888","summary":"The European hare is released on an estancia near Cañada de Gómez, Santa Fe, by the German consul at Rosario. It becomes a continental invasion and eventually a declared national plague — and the ecological basis of an Argentine coursing culture built on English greyhounds and, to a lesser extent, on descendants of the Spanish galgo.","source":"Argentina, Parques Nacionales / SIB; Navas (1987); Grigera & Rapoport (1983).","dimensions":[]},
{"id":"e067","era":8,"position":0.965,"evidence":"probable","date":"1890","title":"The first Spanish dog show","tag":"Retiro 1890","summary":"Five days by the artificial lake in the Retiro, organised by the Vizconde de Irueste. A hundred and fifty dogs, a peseta to get in, and a shortfall of 572 pesetas. Best in show went to a pachón called The; a mastiff called León belonged to the prime minister. Irueste tried and failed to found a Spanish kennel club — an idea realised twenty-one years later.","source":"RSCE-sourced account; month varies between May and 4 June in the sources.","dimensions":[]},
{"id":"e068","era":9,"position":0.015,"evidence":"probable","date":"1910–1915","title":"The first galguero societies","tag":"La Ina","summary":"Sociedad Coto La Ina at Jerez de la Frontera in 1910, El Goloso at Madrid in 1913, and from 1915 the Copa Algete and the Castilian farmers’ and stockmen’s society. The dates come from the federation’s own history; contemporaneous press verification of the first editions has not been obtained.","source":"FEG self-history.","dimensions":[]},
{"id":"e069","era":9,"position":0.055,"evidence":"confirmed","date":"27 Jun 1911","title":"A standard, and a reason for it","tag":"RSCE 1911","summary":"The Sociedad Central de Fomento de las Razas Caninas en España is founded, takes royal patronage from Alfonso XIII in December, joins the FCI in 1912, and recognises the galgo among the first standardised Spanish breeds — fixing the standard in part to resist the Anglo-Spanish crossing already under way. The breed is defined at the moment it is felt to be dissolving.","source":"RSCE official history; legally constituted 12 July 1911.","dimensions":["breed"]},
{"id":"e070","era":9,"position":0.14,"evidence":"confirmed","date":"2 Apr 1930","title":"The oval arrives","tag":"Metropolitano","summary":"The first official track trials are run at Madrid’s Stadium Metropolitano before Alfonso XIII, who had met the fashionable sport in England. The Club Deportivo Galguero promotes them; its secretary, the lawyer Joaquín Losada Pinedo, credits the King with bringing the sport to Spain. A mechanical hare on a curved 400-metre track asks a different question of a dog than an open field does.","source":"Revista de Filología Española (CSIC, 2021) on canódromo vocabulary; Mujeres Españolas interview.","dimensions":["function"]},
{"id":"e071","era":9,"position":0.175,"evidence":"confirmed","date":"1931","title":"Won by a Briton, with a British dog","tag":"1931","summary":"The first Spanish track championship, at the 50,000-seat Metropolitano, is won by George Gray with his greyhound Handy Ben. The sport that would reshape the Spanish galgo arrives fully formed, with its own dogs, and beats the home side.","source":"Racing press and FEG records.","dimensions":[]},
{"id":"e072","era":9,"position":0.21,"evidence":"confirmed","date":"13 Jun 1932","title":"Canódromo Balear","tag":"Palma 1932","summary":"Miquel Rosselló Andreu opens Spain’s oldest track at Palma, having gone to England to learn the business and returned with imported dogs expressly con el fin de criarlos — in order to breed from them. Barcelona’s Sol de Baix follows on 29 July. The importing and the breeding are the same act.","source":"García Gargallo, El Canòdrom Balear (Illa Edicions, 2021).","dimensions":["population"]},
{"id":"e073","era":9,"position":0.25,"evidence":"confirmed","date":"1932–1939","title":"Two interruptions","tag":"","summary":"The Republic’s ban on sports betting halts racing in 1932; the Civil War halts it again from 1936. The national championship only becomes a regular annual fixture from 1940, and pedigree recording in the Libro de Orígenes lapses through the war years. Systematic modern breeding to a fixed standard does not really resume until the late 1970s.","source":"FEG records; RSCE account of native-breed recovery.","dimensions":[]},
{"id":"e074","era":9,"position":0.285,"evidence":"confirmed","date":"8 Dec 1939","title":"Federación Española de Galgos","tag":"FEG 1939","summary":"Constituted as successor to the Club Deportivo Español of 1929–1932. From here the galgo has two institutional lives that never quite meet: the federation governs sport and embraces the greyhound cross for performance; the kennel club governs the standard and the studbook. Nearly every apparent contradiction in the modern breed’s history flows from this split.","source":"FEG; Canódromo Balear founding-member date.","dimensions":[]},
{"id":"e075","era":9,"position":0.34,"evidence":"confirmed","date":"1940–42","title":"Costa Rica, Biscacha, Clarín","tag":"The crossing, in a results table","summary":"The Balearic champions of the first post-war years. Costa Rica, a black bitch born March 1938, bred by Ignacio Lucena, out of the line Dough of Gold; Biscacha out of Grill D’or; Flor de Fergus and Clarín out of Finure Fergus. Spanish-named dogs, Anglo-Irish sire lines. This is what the crossbreeding looks like in the surviving record — not a studbook of hybrid kennels, but a list of winners.","source":"Carreras y Galgos, from FEG federative magazines.","dimensions":["population"]},
{"id":"e076","era":9,"position":0.4,"evidence":"probable","date":"1912–1979","title":"The scale of the infusion","tag":"","summary":"Forty-four dogs shipped from Ireland to Spain between 1912 and 1930; two thousand seven hundred in 1978–79 alone. The infusion was continuous through the century and accelerating. These are Anne Finch’s research figures rather than audited customs data, and should be cited as hers.","source":"Finch, “The Greyhounds and Galgos of Spain,” in All Bets Are Off! (1999).","dimensions":["population"]},
{"id":"e077","era":9,"position":0.46,"evidence":"disproven","date":"The misattribution","title":"“Antonio Miján, the great postwar galgo breeder”","tag":"","summary":"Miján was real, and was a breeder — of the Sabueso Español, a scenthound, under the kennel name Monte Naranco from 1965, and he became that breed’s first specialist judge. No federation or kennel-club source connects him to the galgo. A wrong-breed conflation rather than an invented man, which is exactly how such errors usually enter a breed history.","source":"Asociación del Sabueso Español; independent Spanish and Dutch cynological sources.","dimensions":[]},
{"id":"e078","era":9,"position":0.56,"evidence":"confirmed","date":"1986","title":"The mechanical lure becomes official","tag":"","summary":"Mechanical-lure coursing becomes a federated modality. The racing press dates a related national championship to 1988 — a small date conflict worth flagging rather than smoothing over. Three ways of running a galgo now coexist: the open field, the oval, and the artificial lure.","source":"FEG history; racing press.","dimensions":["function"]},
{"id":"e079","era":9,"position":0.635,"evidence":"unsupported","date":"The date","title":"“Recognised by the FCI in 1972”","tag":"","summary":"Repeated across breed sites and not documented in any FCI source. Recognition is dated 1971 in the sources that can be checked, and the FCI’s own documents anchor to the standard rather than the recognition year.","source":"No FCI source located for 1972.","dimensions":[]},
{"id":"e080","era":9,"position":0.66,"evidence":"confirmed","date":"26 May 1982","title":"Standard No. 285","tag":"FCI 285","summary":"Group 10, sighthounds. Dolichocephalic, eumetric-subconvex, sublongiline; two coats, smooth and rough; all colours admitted; the primordial function given as hunting the hare by sight in open country. Revised texts follow in 1998 and 2002, but the substantive description is stable across all three — the changes are editorial and translational.","source":"FCI Standard No. 285, valid standard dated 26.05.1982; texts 03.06.1998 and 24.05.2002.","dimensions":["breed","type"]},
{"id":"e081","era":9,"position":0.72,"evidence":"confirmed","date":"22 Sep 1980","title":"Club Nacional del Galgo Español","tag":"Two lineages","summary":"The show line formally separates from the working line. Bartolomé Ramírez Castro, the club’s president, is repeatedly credited with preserving and promoting the pure galgo and sheltering unwanted dogs for over forty years. Notably, no named twentieth-century galgo show kennel of consequence appears in the sources — the breed’s century is one of anonymous rural galgueros, not exhibition dynasties.","source":"Club Nacional del Galgo Español; Finch (1999); the 1997 Acto de Desagravio al Galgo.","dimensions":["breed"]},
{"id":"e082","era":9,"position":0.78,"evidence":"confirmed","date":"The federation’s own verdict","title":"“No quedan galgos españoles puros”","tag":"The verdict","summary":"The federation’s own breed material states that purebred Spanish galgos no longer exist in the working and racing population. Half a century of crossing for early speed did what it was designed to do. The sport that made the dog nationally famous also dissolved the thing it was famous for — and this is the federation saying so, not its critics.","source":"FEG breed material.","dimensions":["population","breed"]},
{"id":"e083","era":9,"position":0.855,"evidence":"confirmed","date":"1991","title":"Anne Finch goes to Mallorca","tag":"1991","summary":"She had known of the unwanted-greyhound problem since 1983. In 1991 she travels to Mallorca to investigate the abuses and comes back with four dogs. The same year, the Irish Racing Board bans greyhound exports to Spain in response to abuse reports.","source":"Greyhounds in Need dated diaries; Irish Racing Board.","dimensions":[]},
{"id":"e084","era":9,"position":0.91,"evidence":"confirmed","date":"1995","title":"The hangings","tag":"1995","summary":"After seeing a video in Madrid of galgos hanged in Granada, Finch begins the campaign that makes the practice internationally known. Greyhounds in Need is registered as a charity in May 1998. The welfare crisis becomes the third strand of the galgo’s modern history, alongside sport and cynology.","source":"Greyhounds in Need history; Finch died 5 August 2018.","dimensions":[]},
{"id":"e085","era":9,"position":0.96,"evidence":"confirmed","date":"1999–2000","title":"Palma closes, SOS Galgos opens","tag":"1999","summary":"The Canódromo Balear shuts on 30 March 1999. Some seven hundred racing dogs are left at the closing Barcelona track. SOS Galgos is founded at Esplugues de Llobregat in 2000 by Anna Clements and the vet Albert Sordé in direct response — the end of the tracks becomes the beginning of the rescue movement.","source":"García Gargallo (2021); SOS Galgos; SPCA International.","dimensions":[]},
{"id":"e086","era":10,"position":0.05,"evidence":"confirmed","date":"2005–2006","title":"The last oval","tag":"Meridiana closes","summary":"The final Spanish track championship runs in 2005; the Canódromo Meridiana closes in 2006 and the site becomes a cultural centre. Sixty-five editions of the national track championship, 1931 to 2005. What remains is field coursing — and the estimated tens of thousands of dogs bred to supply it.","source":"García Gargallo (2021); FEG records.","dimensions":[]},
{"id":"e087","era":10,"position":0.1,"evidence":"confirmed","date":"2006","title":"Recognised abroad, barely","tag":"UKC 2006","summary":"The UKC recognises the galgo as the Spanish Greyhound. The AKC does not — there is no US parent club and too few dogs, though the breed is eligible for the Foundation Stock Service — and neither does the UK Kennel Club. The breed’s international presence grew not through show rings but through adoption networks.","source":"UKC standard; AKC FSS criteria; UK Kennel Club breed lists.","dimensions":["breed"]},
{"id":"e088","era":10,"position":0.2,"evidence":"confirmed","date":"1987–2014","title":"A rescue network, not a rescue","tag":"The network","summary":"Scooby at Medina del Campo from 1987; Greyhounds in Need 1998; SOS Galgos and Fundación Benjamín Mehnert 2000; 112 Carlota Galgos and GRIN 2006; Galgos del Sol 2007; SAGE 2011; Love Hope Believe 2013. Roughly seventy per cent of rescued galgos are rehomed outside Spain — northern Italy, Belgium, the Netherlands, Germany, Switzerland, Finland, North America. The largest movement of Spanish sighthounds in history is a welfare diaspora.","source":"Organisation registrations and self-reported histories; verify founding vs. registration dates before citing.","dimensions":["population"]},
{"id":"e089","era":10,"position":0.32,"evidence":"confirmed","date":"16 Nov 2016","title":"Argentina bans dog racing","tag":"Ley 27.330","summary":"Ley 27.330 ends the racing and coursing culture that the 1888 hares had made possible. The largest hub had been the Inriville and Marcos Juárez canódromo in Córdoba province. A hundred and twenty-eight years from four pairs of German hares to a national prohibition.","source":"Argentina, Ley 27.330, sanctioned 16 November 2016.","dimensions":[]},
{"id":"e090","era":10,"position":0.42,"evidence":"confirmed","date":"2018","title":"Yo Galgo","tag":"Yo Galgo","summary":"Yeray López Portillo’s investigative documentary, built around his adopted galga Bacalao, came out of the most successful Spanish crowdfunding campaign in its category — 964 backers, €43,296, in 2016. It collaborated in gathering more than a hundred thousand signatures for a ban on hunting with galgos.","source":"Skinny Dog Films; Kickstarter 27 Feb–7 Apr 2016; IMDb dates the film 2018.","dimensions":[]},
{"id":"e091","era":10,"position":0.52,"evidence":"confirmed","date":"5 Jan 2022","title":"Animals stop being things","tag":"Civil Code","summary":"Law 17/2021 amends the Civil Code, the Mortgage Law and the Law of Civil Procedure so that animals are sentient beings, not property — barring their seizure, abandonment or separation without regard to welfare. In practice the reform is oriented towards pets, which matters a great deal eighteen months later.","source":"Ley 17/2021, of 15 December 2021, in force 5 January 2022.","dimensions":[]},
{"id":"e092","era":10,"position":0.62,"evidence":"confirmed","date":"July 2023","title":"One hundred and twenty-three genomes","tag":"The genome answers","summary":"Whole-genome sequencing of 123 sighthounds establishes that they arose independently in Africa, Europe and the Middle East and are comprehensively admixed. Seventeen positively selected genes in the African population, twenty-seven in the European, fifty-four in the Middle Eastern — with no overlap between the three. What they share is convergence on the same pathways, with functional mutations in ESR1 and JAK2 reducing expression. The lean sighthound body was invented more than once, by people who needed the same thing.","source":"Li, Liu et al. (Wang & Zhang), Molecular Biology and Evolution 40(8):msad158 (2023).","dimensions":["population","type"]},
{"id":"e093","era":10,"position":0.665,"evidence":"disproven","date":"The origin story","title":"“An isolated Celtic lineage”","tag":"","summary":"The romantic narrative — unbroken descent from the canis gallicus, kept pure on the meseta for two thousand years — does not survive the data. Where the galgo has been sequenced it sits among European sighthounds as one admixed population among others. Note what this does not say: coursing in Iberia really is ancient, and the type really is old. It is the closed, isolated pedigree that fails.","source":"Li/Zhang et al. (2023); Parker et al. (2017); Plassais et al. (2019); Dog10K (2023).","dimensions":["population"]},
{"id":"e094","era":10,"position":0.75,"evidence":"confirmed","date":"29 Sep 2023","title":"Law 7/2023, and the amendment","tag":"Law 7/2023","summary":"A genuinely strong companion-animal law: no pet-shop sales of dogs, cats or ferrets; compulsory identification; an owner’s training course; civil liability insurance; fines from €500 to €200,000, with prison up to two years for the worst abuse under the parallel Penal Code reform. Hunting, herding, rescue and police dogs were removed from its scope by an amendment adopted on 22 December 2022, with a separate regulation promised for them. That regulation is still not enacted.","source":"Ley 7/2023 of 28 March, BOE 29 March 2023, in force 29 September 2023; Ley Orgánica 3/2023.","dimensions":[]},
{"id":"e095","era":10,"position":0.81,"evidence":"confirmed","date":"The consequence","title":"Two legal realities for the same animal","tag":"","summary":"The galgo is covered by the Civil Code’s sentience reform and by the Penal Code, and excluded from the companion-animal regime. Because hunting dogs also stay outside the registry system, their births, transfers and deaths remain invisible to the authorities. Legal analysts have argued the split may not survive Article 14 of the Constitution. Avoid the shorthand that galgos have “no protection”: the accurate statement is that they have a different and thinner one.","source":"Law 7/2023 scope provisions; academic commentary on Article 14.","dimensions":[]},
{"id":"e096","era":10,"position":0.875,"evidence":"unsupported","date":"The number","title":"“Fifty to a hundred thousand killed a year”","tag":"The number","summary":"An advocacy projection with no census behind it. Variants run 50,000–70,000, 60,000–80,000, up to 100,000, and they circulate through EU parliamentary questions and the international press. The reasoning — mass overbreeding, roughly one pup in ten kept, disposal at season’s end — is coherent. The figure is still an estimate presented as a count.","source":"SOS Galgos; GRIN; Eurogroup for Animals; EP questions P-000675/2020, E-002928/2024.","dimensions":[]},
{"id":"e097","era":10,"position":0.925,"evidence":"confirmed","date":"March 2025","title":"What the counting actually shows","tag":"2025 study","summary":"Of 15,216 dogs registered lost or abandoned in Spain in 2023, 12.9 per cent were hunting breeds and 2.8 per cent — about 425 — were galgos. Hunting organisations cite this as proof the crisis is exaggerated. Rescuers reply that dogs killed or dumped in the country never reach a shelter and are structurally invisible to intake statistics. Both are right about their own measurement. Neither is a mortality census, and no mortality census exists.","source":"Ministerio de Derechos Sociales, Estudio sobre la Gestión de la Protección Animal en España (March 2025); PACMA (2021).","dimensions":[]},
{"id":"e098","era":10,"position":0.985,"evidence":"confirmed","date":"2026","title":"Where it stands","tag":"2026","summary":"A dog whose function is documented in Iberia for two thousand years, whose name is documented for nine hundred and fifty, whose type is recognisable across all of it, whose population is demonstrably admixed, and whose breed is a hundred and fifteen years old and was defined in the act of being lost. Every one of those five sentences is true at once. Most breed histories try to tell only the first and the last.","source":"Synthesis across the corpus, batches 01–12.","dimensions":["function","type","population","name","breed"]},
];